      ],
      "interpretation": "For each PFAS-resin pair, the authors determined bed volumes at which breakthrough reached 50%, and used these values as quantitative indicators of continuous-flow removal performance.",
      "reported_term": "Bed volumes to 50% PFAS breakthrough in columns"
    },
    {
      "endpoint_type": "sorption",
      "evidence_locator_ids": [
        "S01-E03",
        "S01-E06"
      ],
      "interpretation": "Batch equilibrium experiments (from prior work) provided PFAS-Cl- exchange coefficients (log K_ex) and maximum PFOS adsorption capacities; these sorption parameters are compared qualitatively to pilot-scale breakthrough trends to assess predictive value.",
      "reported_term": "Batch ion exchange affinity constants and maximum adsorption capacity"
    }
  ],
  "limitations": [
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S01-E03"
      ],
      "statement": "Despite large differences in batch-measured maximum PFOS capacity (>4-fold), pilot-column PFOS breakthrough was similar across three single-use resins, indicating that maximum batch capacity alone does not predict continuous-flow performance."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S01-E06"
      ],
      "statement": "Authors note that while empirical correlations between batch-derived exchange coefficients and breakthrough bed volumes are promising, predictions based on these correlations require further validation before use in screening or scaling new resins."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S01-E03"
      ],
      "statement": "Influence of influent PFAS concentration and matrix composition (e.g., NOM) is explicitly highlighted: lower-concentration sites in other pilots experienced complete PFAS breakthrough after adsorption of much lower total PFAS mass, suggesting that site-specific conditions strongly constrain the ability to extrapolate these pilot results."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S01-E03",
        "S01-E05"
      ],
      "statement": "Bench-scale studies with higher NOM levels and longer contact times likely favored polyacrylic A860 in batch, whereas this pilot used shorter EBCTs and different NOM levels, contributing to discrepancies between batch and field performance for A860."
    }
  ],
  "matrix": {
    "evidence_locator_ids": [
      "S01-E01",
      "S01-E03"
    ],
    "value": "Same AFFF-impacted groundwater used in the pilot columns; batch adsorption comparison data referenced from prior studies on similar resins."
  },
  "operating_conditions": [
    {
      "evidence_locator_ids": [
        "S01-E03",
        "S01-E06"
      ],
      "name": "batch_vs_continuous_comparison_basis",
      "qualifiers": "Batch data from earlier Fang et al. (2021) and related studies; breakthrough data from this pilot.",
      "unit": null,
      "value": "Batch equilibrium experiments provided maximum PFOS adsorption capacities and PFAS-Cl- exchange coefficients (log K_ex); pilot columns operated under field groundwater conditions provided bed volumes to 50% breakthrough for the same PFAS-resin combinations."
