        "S01-E07"
      ],
      "name": "continuous_flow_conditions_summary",
      "qualifiers": "",
      "unit": null,
      "value": "Pilot columns operated on site groundwater under fixed EBCT (30-s lead vessel; 2-min combined first two vessels) to generate breakthrough curves for individual PFASs on each resin."
    }
  ],
  "pfas_scope": [
