        "S01-E03"
      ],
      "name": "relative_maximum_capacity_vs_breakthrough",
      "qualifiers": "Macroporous CalRes 2301 had a maximum batch PFOS adsorption capacity >4 times greater than either of the other two gel-type single-use resins, yet PFOS breakthrough data were similar for all three resins in the pilot columns.",
      "unit": null,
      "value": ">4",
      "value_form": "inequality"
    }
  ],
  "record_id": "RT02-bge_llm_local_rag-S01-R03",
  "residuals_byproducts": [
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S01-E02",
        "S01-E04",
        "S01-E06"
      ],
      "statement": "Chromatographic elution behavior and competitive displacement among PFASs in the columns mean that as higher-affinity, more hydrophobic PFASs load onto the resin, they can displace shorter-chain PFASs toward the effluent, complicating direct translation of single-solute batch adsorption metrics to multisolute column performance."
    }
  ],
